// Shows what the agent was allowed to use and what the run cost.
// allowedTools is the exact list the node sent with this invocation.
const BUILT_IN = ['shell', 'read', 'write', 'edit', 'todo_write', 'retrieve_context', 'subagent', 'web_fetch'];
const used = ($json.toolUses ?? []).map((t) => t.name);
const builtInUsed = used.filter((name) => BUILT_IN.includes(name));
const u = $json.usage ?? {};
// With prompt caching, inputTokens counts only the uncached part.
const totalInputTokens =
  (u.inputTokens ?? 0) + (u.cacheReadInputTokens ?? 0) + (u.cacheWriteInputTokens ?? 0);

return [{
  json: {
    answer: $json.response,
    allowedTools: $json.allowedTools ?? 'unrestricted',
    toolsUsed: used,
    builtInToolsUsed: builtInUsed,
    withinPolicy: builtInUsed.length === 0,
    tags: $json.tags ?? {},
    truncation: $json.harness?.truncation ?? 'service default',
    totalInputTokens,
    outputTokens: u.outputTokens ?? 0,
    cachedInputTokens: (u.cacheReadInputTokens ?? 0) + (u.cacheWriteInputTokens ?? 0),
  },
}];
